//! Small process-wide state shared by every module (owned by the orchestrator; module workers do not edit this file).
use parking_lot::Mutex;
use std::collections::HashSet;
use std::path::PathBuf;
use std::sync::LazyLock;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

pub const HAIKU_PER_HOUR: usize = 150;
pub const AWAKE_S: f64 = 300.0;
pub const RECENT: f64 = 2.0 * 3600.0;
pub const LINGER: f64 = 15.0 * 60.0;

pub fn now() -> f64 {
    agencia_core::types::now_unix_secs()
}
pub fn home() -> String {
    agencia_core::types::home_dir().to_string_lossy().into_owned()
}
/// ~/Agencia (AGENCIA_DIR / AGENCIA_ROOT override). Jobs, cache and shots live here.
pub fn root() -> PathBuf {
    agencia_core::types::agencia_root()
}
/// Static SPA directory: AGENCIA_WEB / AGENCIA_WEB_DIR, else <root>/web, else <exe>/../../../web, else ./web.
pub fn web_dir() -> PathBuf {
    for key in ["AGENCIA_WEB", "AGENCIA_WEB_DIR"] {
        if let Some(p) = std::env::var_os(key).filter(|v| !v.is_empty()) {
            return PathBuf::from(p);
        }
    }
    let from_root = root().join("web");
    if from_root.is_dir() {
        return from_root;
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(repo) = exe.parent().and_then(|p| p.parent()).and_then(|p| p.parent()) {
            let candidate = repo.join("web");
            if candidate.is_dir() {
                return candidate;
            }
        }
    }
    PathBuf::from("web")
}
pub fn cache_dir() -> PathBuf {
    root().join("cache")
}
pub fn port() -> u16 {
    std::env::var("AGENCIA_PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(8800)
}
/// Test instances set AGENCIA_NO_LOOPS=1: no narrator, janitor, safe judge, reconcile or real loops (no model calls, no archiving).
pub fn loops_enabled() -> bool {
    std::env::var_os("AGENCIA_NO_LOOPS").is_none()
}

// ---- OWNER pulse: the page POSTs /api/pulse; model-calling loops sleep AWAKE_S after the last one ----
static PULSE: AtomicU64 = AtomicU64::new(0);
pub fn pulse() {
    PULSE.store(now() as u64, Ordering::Relaxed);
}
pub fn awake() -> bool {
    now() - (PULSE.load(Ordering::Relaxed) as f64) < AWAKE_S
}

// ---- snapshot cache invalidation (a POST that changes state asks the next /api/state to rebuild) ----
static DIRTY: AtomicBool = AtomicBool::new(false);
pub fn invalidate() {
    DIRTY.store(true, Ordering::Relaxed);
}
/// Returns true once after invalidate().
pub fn take_dirty() -> bool {
    DIRTY.swap(false, Ordering::Relaxed)
}

// ---- cards the OWNER cleaned off the board for good (cache/limpios.json, kept across restarts) ----
static HIDE: LazyLock<Mutex<HashSet<String>>> = LazyLock::new(|| {
    let v: Vec<String> = std::fs::read(cache_dir().join("limpios.json"))
        .ok()
        .and_then(|b| serde_json::from_slice(&b).ok())
        .unwrap_or_default();
    Mutex::new(v.into_iter().collect())
});
pub fn hidden(id: &str) -> bool {
    HIDE.lock().contains(id)
}
pub fn hide<I: IntoIterator<Item = String>>(ids: I) {
    let mut h = HIDE.lock();
    h.extend(ids);
    let mut v: Vec<&String> = h.iter().collect();
    v.sort();
    let start = v.len().saturating_sub(5000);
    let _ = std::fs::write(cache_dir().join("limpios.json"), serde_json::to_vec(&v[start..]).unwrap_or_default());
}
